import { DataElement, TrackedEntityAttribute } from "@hisptz/dhis2-utils";
import {
	SupportedDataTypeNames,
	supportedDataTypes,
} from "../../../script/constants/dataTypes";
import { DataType } from "../../../script/interfaces";

export type DataItem = TrackedEntityAttribute | DataElement;

/*
 * The generators that can produce valid values for a field: option sets only use Options,
 * auto generated attributes only use Autogenerated, everything else is matched on value type.
 */
export function getSupportedGenerators(dataItem: DataItem): DataType[] {
	const hasOptionSet = !!dataItem.optionSet;
	const generated = !!(dataItem as TrackedEntityAttribute).generated;

	return supportedDataTypes.filter(({ dhis2Fields, name }) => {
		if (hasOptionSet !== (name === SupportedDataTypeNames.OPTIONS)) {
			return false;
		}
		if (generated !== (name === SupportedDataTypeNames.AUTOGENERATED)) {
			return false;
		}
		return (
			(!!dataItem.valueType && dhis2Fields.includes(dataItem.valueType)) ||
			dhis2Fields.length === 0
		);
	});
}

export function getGeneratorOptions(dataItem: DataItem) {
	return getSupportedGenerators(dataItem).map(({ name }) => ({
		label: name,
		value: name,
	}));
}
